import cv2
import numpy as np
import json
import sys
import os
import re
import argparse
from pathlib import Path


# 1. Set up argument parsing
parser = argparse.ArgumentParser(description="Zone a 2-column book page into a continuous, non-overlapping grid layout.")
parser.add_argument("image_path", help="Path to the source page image file.")
parser.add_argument("-v", "--visualize", action="store_true", help="Generate a colored visualization image showing element boundaries.")
parser.add_argument("-e", "--extract", action="store_true", help="Extract and save cropped images for each layout element.")
args = parser.parse_args()

#filename = os.path.basename(args.image_path)

image_path = args.image_path

output_root = Path(f"training-data/page-{Path(image_path).stem}")
if output_root.is_dir():
    print(f"dir exists: {output_root}")
else:
    os.mkdir(output_root)

element_dir = output_root / "page-elements"
if not element_dir.is_dir():
    os.mkdir(element_dir)

# 2. Extract the 8-digit ID from the filename using a regular expression
id_match = re.search(r'\b\d{8}\b', image_path)
if id_match:
    image_id = id_match.group(0)
else:
    print(f"Error: Could not find an 8-digit ID in the filename '{image_path}'.")
    sys.exit(1)

# 3. Load the image
img = cv2.imread(args.image_path)
if img is None:
    print(f"Error: Could not load image from {args.image_path}")
    sys.exit(1)

h_img, w_img = img.shape[:2]

# 4. Define structural anchors for the parchment leaf area
page_left = int(w_img * 0.25)     
page_right = int(w_img * 0.90)    
page_top = int(h_img * 0.13)      
page_bottom = int(h_img * 0.77)   

# 5. Create a clean binary mask of the active text area using Adaptive Thresholding
gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
paper_roi = gray[page_top:page_bottom, page_left:page_right]

thresh = cv2.adaptiveThreshold(
    paper_roi, 255, cv2.ADAPTIVE_THRESH_GAUSSIAN_C, 
    cv2.THRESH_BINARY_INV, 51, 15
)

# 6. Locate the central text dividing gutter
horiz_profile = np.sum(thresh, axis=0)
roi_width = page_right - page_left
mid_x = roi_width // 2

gutter_search_zone = horiz_profile[mid_x - 30 : mid_x + 30]
exact_gutter_local = (mid_x - 30) + np.argmin(gutter_search_zone)

# 7. Helper function to find raw text boundaries
def locate_raw_text(start_x, end_x, global_offset_x):
    column_strip = thresh[:, start_x:end_x]
    density_profile = np.sum(column_strip, axis=0)
    
    cutoff = np.max(density_profile) * 0.35
    dense_x_indices = np.where(density_profile > cutoff)[0]
    
    if len(dense_x_indices) == 0:
        return None
        
    first_x = int(dense_x_indices[0])
    last_x = int(dense_x_indices[-1])
    
    left_x = global_offset_x + start_x + first_x
    right_x = global_offset_x + start_x + last_x

    text_column_block = thresh[:, (start_x + first_x) : (start_x + last_x)]
    row_profile = np.sum(text_column_block, axis=1)
    dense_y_indices = np.where(row_profile > (np.max(row_profile) * 0.1))[0]
    
    if len(dense_y_indices) == 0:
        return None
        
    first_y = int(dense_y_indices[0])
    last_y = int(dense_y_indices[-1])
    
    top_y = page_top + first_y
    bottom_y = page_top + last_y
    
    return (left_x, top_y, right_x, bottom_y)

# Get initial tightly bound text lines
left_raw = locate_raw_text(0, exact_gutter_local - 10, page_left)
right_raw = locate_raw_text(exact_gutter_local + 10, roi_width, page_left)

if not left_raw or not right_raw:
    print("Error: Could not isolate text columns properly.")
    sys.exit(1)

# 8. Apply 15px padding rules and establish unified vertical lines
padding = 15

# Determine the unified top and bottom for both main blocks (padded)
unified_top = int(max(0, min(left_raw[1], right_raw[1]) - padding))
unified_bottom = int(min(h_img, max(left_raw[3], right_raw[3]) + padding))
middle_row_height = int(unified_bottom - unified_top)

# Apply 15px horizontal padding to both columns, clamping inside image limits
left_col_x = int(max(0, left_raw[0] - padding))
left_col_r = int(min(w_img, left_raw[2] + padding))
left_col_w = int(left_col_r - left_col_x)

right_col_x = int(max(0, right_raw[0] - padding))
right_col_r = int(min(w_img, right_raw[2] + padding))
right_col_w = int(right_col_r - right_col_x)

# 9. Complete the Tiling Grid (No overlap, no unassigned pixels)
zones_json = {
    "top_margin": {
        "x": 0, "y": 0, "w": int(w_img), "h": unified_top
    },
    "left_margin": {
        "x": 0, "y": unified_top, "w": left_col_x, "h": middle_row_height
    },
    "left_column": {
        "x": left_col_x, "y": unified_top, "w": left_col_w, "h": middle_row_height
    },
    "inter_column_space": {
        "x": left_col_r, "y": unified_top, "w": int(right_col_x - left_col_r), "h": middle_row_height
    },
    "right_column": {
        "x": right_col_x, "y": unified_top, "w": right_col_w, "h": middle_row_height
    },
    "right_margin": {
        "x": right_col_r, "y": unified_top, "w": int(w_img - right_col_r), "h": middle_row_height
    },
    "bottom_margin": {
        "x": 0, "y": unified_bottom, "w": int(w_img), "h": int(h_img - unified_bottom)
    }
}

# 10. Write the JSON data to the target output directory
json_dir = output_root / "page-elements"
os.makedirs(json_dir, exist_ok=True)
output_json_path = os.path.join(output_root, f"{image_id}-dimensions.json")

# print(f"Will write json to {output_json_path}")

with open(output_json_path, 'w', encoding='utf-8') as json_file:
    json.dump(zones_json, json_file, indent=4)
print(f"Success! Contiguous page grid zones exported to: {output_json_path}")

# 11. Optional extraction of element images
if args.extract:
    extract_dir = output_root / "page-elements"
    os.makedirs(extract_dir, exist_ok=True)
    
    # Map internal zone names to the requested output file suffixes
    suffix_map = {
        "top_margin": "top-margin",
        "bottom_margin": "bottom-margin",
        "left_margin": "left-margin",
        "right_margin": "right-margin",
        "left_column": "left-text",
        "right_column": "right-text",
        "inter_column_space": "centre-margin"
    }

    # Extract file extension from input image path
    ext = os.path.splitext(args.image_path)[1]
    if not ext:
        ext = ".jpg"

    for zone_key, box in zones_json.items():
        # breakpoint()
        if box['w'] > 0 and box['h'] > 0:
            crop = img[box['y']:box['y'] + box['h'], box['x']:box['x'] + box['w']]
            suffix = suffix_map[zone_key]
            crop_filename = f"{image_id}-{suffix}{ext}"
            crop_path = os.path.join(extract_dir, crop_filename)
            cv2.imwrite(crop_path, crop)

    print(f"Successfully extracted elements to: {extract_dir}/")

# breakpoint()

# 12. Optional visualization layer logic
if args.visualize:
    img_dir = "page-elements"
    os.makedirs(img_dir, exist_ok=True)
    output_img_path = os.path.join(output_root, f"{image_id}-dimensions.jpg")
    
    # Define distinctive colors for each bounded zone (BGR format)
    colors = {
        "top_margin": (200, 200, 200),        # Light Gray
        "left_margin": (0, 165, 255),         # Orange
        "left_column": (0, 255, 0),           # Green
        "inter_column_space": (255, 255, 0),  # Cyan
        "right_column": (0, 255, 255),        # Yellow
        "right_margin": (255, 0, 165),        # Magenta
        "bottom_margin": (100, 100, 100)      # Dark Gray
    }
    
    overlay = img.copy()
    for zone_name, box in zones_json.items():
        # Draw solid bounding tiles onto overlay canvas
        cv2.rectangle(
            overlay, 
            (box['x'], box['y']), 
            (box['x'] + box['w'], box['y'] + box['h']), 
            colors[zone_name], 
            -1
        )
        
    # Merge overlay with opacity so source layout lines peek through
    cv2.addWeighted(overlay, 0.25, img, 0.75, 0, img)
    
    # Draw dark black grid lines between bounding edges for crisp visual structure
    for box in zones_json.values():
        cv2.rectangle(
            img, 
            (box['x'], box['y']), 
            (box['x'] + box['w'], box['y'] + box['h']), 
            (0, 0, 0), 
            2
        )
        
    cv2.imwrite(output_img_path, img)
    print(f"Visualization overlay successfully exported to: {output_img_path}")
